package io.github.aplite36.chunkcarts.core.fake;

import io.github.aplite36.chunkcarts.core.platform.CartView;
import io.github.aplite36.chunkcarts.core.ChunkPos;
import io.github.aplite36.chunkcarts.core.WorldId;
import io.github.aplite36.chunkcarts.core.platform.WorldQuery;

import java.util.HashSet;
import java.util.LinkedHashSet;
import java.util.Set;
import java.util.UUID;
import java.util.concurrent.CompletableFuture;

/**
 * A world the test describes explicitly.
 *
 * <p>Everything is generated by default, because {@code UNGENERATED_CHUNK} should be something a
 * test opts into rather than a trap every other test has to remember to disarm.
 *
 * <p><strong>Player-loaded chunks are tracked completely separately from the ticket backend</strong>
 * and this fake has no access to it. That is deliberate: it mirrors the constraint from §3.3 that
 * a chunk the plugin is holding must never grant a token. If this fake could see held chunks, the
 * circularity guard test could pass while the real adapter was wrong.
 */
public final class FakeWorldQuery implements WorldQuery {

    private final Set<ChunkPos> ungenerated = new HashSet<>();
    private final Set<ChunkPos> playerLoaded = new HashSet<>();
    private final Set<UUID> offRail = new HashSet<>();
    private final Set<ChunkPos> prefetched = new LinkedHashSet<>();

    @Override
    public boolean isGenerated(WorldId world, int cx, int cz) {
        return !ungenerated.contains(new ChunkPos(world, cx, cz));
    }

    @Override
    public boolean isPlayerLoaded(WorldId world, int cx, int cz) {
        return playerLoaded.contains(new ChunkPos(world, cx, cz));
    }

    @Override
    public CompletableFuture<Void> prefetch(WorldId world, int cx, int cz) {
        prefetched.add(new ChunkPos(world, cx, cz));
        return CompletableFuture.completedFuture(null);
    }

    @Override
    public boolean isOnRail(CartView cart) {
        return !offRail.contains(cart.id());
    }

    public FakeWorldQuery withPlayerLoaded(WorldId world, int cx, int cz) {
        playerLoaded.add(new ChunkPos(world, cx, cz));
        return this;
    }

    /** Player-loaded square of the given chunk radius, as real player presence would be. */
    public FakeWorldQuery withPlayerLoadedArea(WorldId world, int cx, int cz, int radius) {
        for (int dx = -radius; dx <= radius; dx++) {
            for (int dz = -radius; dz <= radius; dz++) {
                playerLoaded.add(new ChunkPos(world, cx + dx, cz + dz));
            }
        }
        return this;
    }

    public FakeWorldQuery withoutPlayerLoaded(WorldId world, int cx, int cz) {
        playerLoaded.remove(new ChunkPos(world, cx, cz));
        return this;
    }

    public FakeWorldQuery clearPlayerLoaded() {
        playerLoaded.clear();
        return this;
    }

    public FakeWorldQuery withUngenerated(WorldId world, int cx, int cz) {
        ungenerated.add(new ChunkPos(world, cx, cz));
        return this;
    }

    public FakeWorldQuery derail(UUID cartId) {
        offRail.add(cartId);
        return this;
    }

    public Set<ChunkPos> prefetched() {
        return Set.copyOf(prefetched);
    }
}
